package com.knowledge.app;
import com.knowledge.app.model.entity.*;
import com.knowledge.app.repository.*;
import com.knowledge.app.service.user.*;
import com.knowledge.app.model.dto.request.user.*;
import com.jayway.jsonpath.JsonPath;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.zip.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class SprintTwoIntegrationTest {
 @Autowired MockMvc mvc;@Autowired UserService users;@Autowired RoleRepository roles;@Autowired DocumentRepository docs;@Autowired DocumentFileRepository files;@Autowired DocumentDownloadRepository downloads;@Autowired CategoryRepository categories;@Autowired SubjectRepository subjects;@Autowired InstitutionRepository institutions;@Autowired FacultyRepository faculties;@Autowired ProfileService profiles;@Autowired DocumentBookmarkRepository bookmarks;
 long member,other,admin,category,subject,school,faculty;String token,otherToken,adminToken;static final String PASSWORD="Sprint2-password!";
 @BeforeEach void setup()throws Exception{for(String name:Set.of("USER","ADMIN"))if(roles.findByName(name).isEmpty()){var role=new Role();role.setName(name);roles.saveAndFlush(role);}member=users.create(new AdminCreateUserRequest("s2member","s2member@example.test",PASSWORD,Set.of("USER"))).id();other=users.create(new AdminCreateUserRequest("s2other","s2other@example.test",PASSWORD,Set.of("USER"))).id();admin=users.create(new AdminCreateUserRequest("s2admin","s2admin@example.test",PASSWORD,Set.of("ADMIN"))).id();var c=new Category();c.setName("Sprint 2 topic");c.setSlug("sprint-two-topic");c.setActive(true);c.setSortOrder(0);category=categories.saveAndFlush(c).getId();var sub=new Subject();sub.setName("Sprint 2 subject");sub.setSlug("sprint-two-subject");subject=subjects.saveAndFlush(sub).getId();var i=new Institution();i.setName("Sprint 2 university");i.setType("UNIVERSITY");school=institutions.saveAndFlush(i).getId();var f=new Faculty();f.setName("Sprint 2 faculty");f.setInstitution(i);faculty=faculties.saveAndFlush(f).getId();profiles.update(member,new UpdateProfileRequest(null,null,school,faculty));token=login("s2member");otherToken=login("s2other");adminToken=login("s2admin");}
 @Test void uploadDefaultsToProfileOrganizationAndPendingWithSubjectAndTags()throws Exception{long id=upload(token,"lesson.txt","text/plain","Giáo trình Java tiếng Việt 📚".getBytes(StandardCharsets.UTF_8),metadata("Sprint2 Lesson"));var d=docs.findById(id).orElseThrow();assertEquals("PENDING",d.getStatus());assertEquals(school,d.getInstitution().getId());assertEquals(faculty,d.getFaculty().getId());assertEquals(subject,d.getSubject().getId());assertEquals(2,d.getTags().size());mvc.perform(get("/api/documents/"+id)).andExpect(status().isNotFound());mvc.perform(get("/api/documents/"+id).header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("PENDING"));mvc.perform(get("/api/users/me/documents").header("Authorization","Bearer "+token)).andExpect(jsonPath("$.data.totalElements").value(1));mvc.perform(get("/api/users/me/documents").header("Authorization","Bearer "+otherToken)).andExpect(jsonPath("$.data.totalElements").value(0));}
 @Test void uploadNeedsCategoryAndRejectsTooManyTags()throws Exception{rejectUpload(metadata("Invalid").replace("\"categoryId\":"+category,"\"categoryId\":null"));rejectUpload(metadata("Invalid").replace("[\"Java\",\"Ôn tập\"]","[\"a\",\"b\",\"c\",\"d\",\"e\",\"f\"]"));rejectUpload(metadata("Invalid").replace("\"subjectId\":"+subject,"\"subjectId\":999999999"));}
 @Test void uploadsAcceptExactly20MiBAndRejectLarger()throws Exception{byte[] bytes=new byte[20*1024*1024];Arrays.fill(bytes,(byte)'a');upload(token,"boundary.txt","text/plain",bytes,metadata("Sprint2 Boundary"));mvc.perform(multipart("/api/documents").file(meta(metadata("Too big"))).file(new MockMultipartFile("file","too-big.txt","text/plain",new byte[20*1024*1024+1])).header("Authorization","Bearer "+token)).andExpect(status().isBadRequest());}
 @Test void powerpointAndPdfContentIsValidated()throws Exception{upload(token,"slides.pptx","application/octet-stream",pptx(false),metadata("Sprint2 Slides"));mvc.perform(multipart("/api/documents").file(meta(metadata("Bad slides"))).file(new MockMultipartFile("file","bad.pptx","application/octet-stream","not zip".getBytes())).header("Authorization","Bearer "+token)).andExpect(status().isBadRequest());mvc.perform(multipart("/api/documents").file(meta(metadata("Macro"))).file(new MockMultipartFile("file","macro.pptx","application/octet-stream",pptx(true))).header("Authorization","Bearer "+token)).andExpect(status().isBadRequest());mvc.perform(multipart("/api/documents").file(meta(metadata("Fake PDF"))).file(new MockMultipartFile("file","fake.pdf","application/pdf","not pdf".getBytes())).header("Authorization","Bearer "+token)).andExpect(status().isBadRequest());}
 @Test void reviewPreviewDoesNotRecordDownloadsAndIsPrivate()throws Exception{long id=textUpload();long file=files.findByDocumentIdAndActiveTrueOrderByIdAsc(id).get(0).getId();mvc.perform(get(preview(id,file)).header("Authorization","Bearer "+adminToken)).andExpect(status().isOk()).andExpect(content().bytes("Sprint 2 content".getBytes()));mvc.perform(get(preview(id,file)).header("Authorization","Bearer "+otherToken)).andExpect(status().isForbidden());mvc.perform(get(preview(id,file))).andExpect(status().isUnauthorized());mvc.perform(get(preview(id,99999999)).header("Authorization","Bearer "+token)).andExpect(status().isNotFound());assertEquals(0,downloads.countByDocumentId(id));mvc.perform(post(download(id,file)).header("Authorization","Bearer "+token)).andExpect(status().isNotFound());}
 @Test void approveEnablesDownloadAndEverySuccessfulDownloadIsRecorded()throws Exception{long id=textUpload();review(id,"APPROVE",null,200);long file=files.findByDocumentIdAndActiveTrueOrderByIdAsc(id).get(0).getId();for(int n=0;n<2;n++)mvc.perform(post(download(id,file)).header("Authorization","Bearer "+otherToken)).andExpect(status().isOk());assertEquals(2,downloads.countByDocumentId(id));mvc.perform(get("/api/documents").param("q","Sprint2").param("subjectId",String.valueOf(subject)).param("institutionId",String.valueOf(school)).param("facultyId",String.valueOf(faculty)).param("tag","Java")).andExpect(jsonPath("$.data.totalElements").value(1));mvc.perform(get("/api/documents").param("q","Sprint2").param("tag","missing")).andExpect(jsonPath("$.data.totalElements").value(0));}
 @Test void rejectionNeedsReasonAndAuthorCanResubmit()throws Exception{long id=textUpload();review(id,"REJECT",null,400);review(id,"REJECT","Cần bổ sung nguồn tài liệu",200);mvc.perform(get("/api/documents/"+id).header("Authorization","Bearer "+token)).andExpect(jsonPath("$.data.reviewNote").value("Cần bổ sung nguồn tài liệu"));edit(id,token,false,"Sprint2 Updated",200);assertEquals("PENDING",docs.findById(id).orElseThrow().getStatus());review(id,"APPROVE",null,200);edit(id,token,false,"Sprint2 Resubmitted",200);assertEquals("PENDING",docs.findById(id).orElseThrow().getStatus());mvc.perform(get("/api/documents/"+id)).andExpect(status().isNotFound());}
 @Test void ownershipAdminRoleAndStaleVersionAreEnforced()throws Exception{long id=textUpload();edit(id,otherToken,false,"Attack",403);edit(id,otherToken,true,"Attack",403);mvc.perform(post("/api/admin/documents/"+id+"/review").header("Authorization","Bearer "+otherToken).contentType("application/json").content("{\"version\":0,\"action\":\"APPROVE\"}")).andExpect(status().isForbidden());edit(id,adminToken,true,"Sprint2 Admin corrected",200);mvc.perform(put("/api/users/me/documents/"+id).header("Authorization","Bearer "+token).contentType("application/json").content("{\"version\":0,\"metadata\":"+metadata("Stale")+"}")).andExpect(status().isConflict());mvc.perform(get("/api/admin/documents").header("Authorization","Bearer "+otherToken)).andExpect(status().isForbidden());}
 @Test void hideRestoreAndSoftDeletePreserveHistory()throws Exception{long id=textUpload();review(id,"APPROVE",null,200);long file=files.findByDocumentIdAndActiveTrueOrderByIdAsc(id).get(0).getId();mvc.perform(post(download(id,file)).header("Authorization","Bearer "+otherToken)).andExpect(status().isOk());mvc.perform(post("/api/users/me/bookmarks/"+id).header("Authorization","Bearer "+otherToken).contentType("application/json").content("{\"saved\":true}")).andExpect(status().isOk());review(id,"HIDE",null,200);mvc.perform(get("/api/documents/"+id)).andExpect(status().isNotFound());mvc.perform(post(download(id,file)).header("Authorization","Bearer "+otherToken)).andExpect(status().isNotFound());review(id,"RESTORE",null,200);mvc.perform(delete("/api/users/me/documents/"+id).param("version",version(id)).header("Authorization","Bearer "+otherToken)).andExpect(status().isForbidden());mvc.perform(delete("/api/admin/documents/"+id).param("version",version(id)).header("Authorization","Bearer "+adminToken)).andExpect(status().isOk());assertEquals("DELETED",docs.findById(id).orElseThrow().getStatus());assertEquals(1,downloads.countByDocumentId(id));assertEquals(1,files.findByDocumentIdAndActiveTrueOrderByIdAsc(id).size());mvc.perform(get("/api/users/me/downloads").header("Authorization","Bearer "+otherToken)).andExpect(jsonPath("$.data.content[0].available").value(false));mvc.perform(get("/api/users/me/bookmarks").header("Authorization","Bearer "+otherToken)).andExpect(jsonPath("$.data.totalElements").value(0));}
 @Test void officeTextPreviewUsesRealSlideAndRemainsPrivate()throws Exception{byte[] bytes;try(var input=getClass().getResourceAsStream("/library/sprint2-slides.pptx")){bytes=input.readAllBytes();}long id=upload(token,"slides.pptx","application/octet-stream",bytes,metadata("Sprint2 Real Slides"));long file=files.findByDocumentIdAndActiveTrueOrderByIdAsc(id).get(0).getId();mvc.perform(get("/api/documents/"+id+"/files/"+file+"/preview-text").header("Authorization","Bearer "+adminToken)).andExpect(status().isOk()).andExpect(jsonPath("$.data").value(org.hamcrest.Matchers.containsString("Knowledge Hub")));mvc.perform(get("/api/documents/"+id+"/files/"+file+"/preview-text").header("Authorization","Bearer "+otherToken)).andExpect(status().isForbidden());assertEquals(0,downloads.countByDocumentId(id));}
 @Test void adminCanAddAndEditPublishedTextbook()throws Exception{long id=upload(adminToken,"textbook.txt","text/plain","Official textbook".getBytes(),metadata("Sprint2 Official"));assertEquals("PUBLISHED",docs.findById(id).orElseThrow().getStatus());edit(id,adminToken,true,"Sprint2 Official corrected",200);assertEquals("PUBLISHED",docs.findById(id).orElseThrow().getStatus());mvc.perform(get("/api/documents/"+id)).andExpect(status().isOk());}
 private long textUpload()throws Exception{return upload(token,"notes.txt","text/plain","Sprint 2 content".getBytes(),metadata("Sprint2 Lesson"));}
 private long upload(String jwt,String name,String type,byte[] data,String metadata)throws Exception{var result=mvc.perform(multipart("/api/documents").file(meta(metadata)).file(new MockMultipartFile("file",name,type,data)).header("Authorization","Bearer "+jwt)).andExpect(status().isCreated()).andReturn();return ((Number)JsonPath.read(result.getResponse().getContentAsString(),"$.data.id")).longValue();}
 private void rejectUpload(String metadata)throws Exception{mvc.perform(multipart("/api/documents").file(meta(metadata)).file(new MockMultipartFile("file","notes.txt","text/plain","text".getBytes())).header("Authorization","Bearer "+token)).andExpect(status().isBadRequest());}
 private MockMultipartFile meta(String json){return new MockMultipartFile("metadata","metadata","application/json",json.getBytes(StandardCharsets.UTF_8));}
 private String metadata(String title){return "{\"title\":\""+title+"\",\"summary\":\"Tóm tắt tiếng Việt\",\"description\":\"Nội dung giáo trình\",\"categoryId\":"+category+",\"level\":\"BEGINNER\",\"accessType\":\"FREE\",\"price\":0,\"subjectId\":"+subject+",\"tags\":[\"Java\",\"Ôn tập\"]}";}
 private String version(long id){return docs.findById(id).orElseThrow().getVersion().toString();}
 private void edit(long id,String jwt,boolean adminMode,String title,int expected)throws Exception{mvc.perform(put("/api/"+(adminMode?"admin":"users/me")+"/documents/"+id).header("Authorization","Bearer "+jwt).contentType("application/json").content("{\"version\":"+version(id)+",\"metadata\":"+metadata(title)+"}")).andExpect(status().is(expected));}
 private void review(long id,String action,String note,int expected)throws Exception{mvc.perform(post("/api/admin/documents/"+id+"/review").header("Authorization","Bearer "+adminToken).contentType("application/json").content("{\"version\":"+version(id)+",\"action\":\""+action+"\",\"note\":"+(note==null?"null":"\""+note+"\"")+"}")).andExpect(status().is(expected));}
 private String login(String username)throws Exception{var result=mvc.perform(post("/api/auth/login").param("username",username).param("password",PASSWORD)).andExpect(status().isOk()).andReturn();return JsonPath.read(result.getResponse().getContentAsString(),"$.data.accessToken");}
 private String preview(long id,long file){return "/api/documents/"+id+"/files/"+file+"/preview";}private String download(long id,long file){return "/api/documents/"+id+"/files/"+file+"/download";}
 private byte[] pptx(boolean macro)throws Exception{var bytes=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(bytes)){for(String name:macro?List.of("[Content_Types].xml","ppt/presentation.xml","ppt/vbaProject.bin"):List.of("[Content_Types].xml","ppt/presentation.xml")){zip.putNextEntry(new ZipEntry(name));zip.write("<xml/>".getBytes());zip.closeEntry();}}return bytes.toByteArray();}
}
